    `<script src="${base}/alireza/workspace/ui.js?v=${uiVersion}"></script><script src="${base}/alireza/network/ui.js?v=${uiVersion}"></script><script data-alireza-addon src="${base}/alireza/brand.js?v=${uiVersion}"></script><script src="${base}/alireza/manual/core.js?v=${uiVersion}"></script><script src="${base}/alireza/manual/editor.js?v=${uiVersion}"></script><script src="${base}/alireza/bot/ui.js?v=${uiVersion}"></script><script src="${base}/alireza/hashem/ui.js?v=${uiVersion}"></script><script src="${base}/alireza/openvpn/inline.js?v=${uiVersion}"></script><script src="${base}/alireza/manual/native.js?v=${uiVersion}"></script><script src="${base}/alireza/inbounds/ui.js?v=${uiVersion}"></script></body>`);
