function shopContext(port,base){return{native:owner=>scopedNative(owner,port,base),mainToken:bot.isMainToken,panelURL:async()=>publicOrigin(settings())+base+'/'};}
async function handle(req,res,base,tail) {
  if(tail==='api/instance'&&req.method==='GET'){json(res,200,{product:'alirezaserver',instance:instanceID()});return;}
  const ui={'network/ui.js':'network-ui.js','workspace/ui.js':'workspace-ui.js','manual/native.js':'manual-native.js','openvpn/inline.js':'openvpn-inline.js'};
  if(ui[tail]&&req.method==='GET'){file(res,ui[tail],'text/javascript; charset=utf-8');return;}
  if(['manual/core.js','manual/editor.js'].includes(tail)&&req.method==='GET'){file(res,tail==='manual/core.js'?'manual-core.js':'manual-editor.js','text/javascript; charset=utf-8');return;}
  // Public static UI code only; all account/service APIs still require native owner auth.
  if(tail==='inbounds/ui.js'&&req.method==='GET'){file(res,'inbounds-ui.js','text/javascript; charset=utf-8');return;}
  if(tail==='brand.js'&&req.method==='GET'){file(res,'brand.js','text/javascript; charset=utf-8');return;}
  if(tail==='hashem/ui.js'&&req.method==='GET'){file(res,'hashem-ui.js','text/javascript; charset=utf-8');return;}
  if(tail==='bot/ui.js'&&req.method==='GET'){file(res,'bot-ui.js','text/javascript; charset=utf-8');return;}
  if(tail==='hashem/source.tar.gz'&&req.method==='GET'){const data=Buffer.from(readFileSync(join(HERE,'hashem-source.tar.b64'),'utf8'),'base64');res.writeHead(200,{'content-type':'application/gzip','content-disposition':'attachment; filename=alirezaserver-hashem-source.tar.gz','cache-control':'public, max-age=300','x-content-type-options':'nosniff'});res.end(data);return;}
  if((tail==='bot/source.tar.gz'||tail==='bot/web/source.tar.gz')&&req.method==='GET'){const data=Buffer.from(readFileSync(join(HERE,'alirezabot-source.tar.b64'),'utf8'),'base64');res.writeHead(200,{'content-type':'application/gzip','content-disposition':'attachment; filename=alirezabot-source.tar.gz','cache-control':'public, max-age=300','x-content-type-options':'nosniff'});res.end(data);return;}
  const tenantRoute=tail.match(/^bot\/tenant\/([a-f0-9]{24})\/(web\/|sub\/)(.*)$/);
  if(tenantRoute){const[,key,kind,rest]=tenantRoute;if(!tenantBot.read(key)){json(res,404,{error:'Not found'});return;}if(kind==='web/'){await phpProxy(req,res,rest+(req.url.includes('?')?'?'+req.url.split('?')[1]:''),base+'/alireza/bot/tenant/'+key+'/web/',tenantBot.paths(key));return;}const url=await tenantBot.bridge(key,shopContext(apiPort(req),base)).subscription(rest);if(!url){json(res,404,{error:'Invalid subscription'});return;}res.writeHead(302,{location:url,'cache-control':'no-store','referrer-policy':'no-referrer'});res.end();return;}
  const tenantAPI=tail.match(/^api\/bot-tenant\/([a-f0-9]{24})\/(.*)$/);
