  if(!['GET','HEAD'].includes(req.method)&&!sameOrigin(req)){json(res,403,{error:'Same-origin request required'});return;}
  if(tail==='api/hashem/logs'&&req.method==='GET'){json(res,200,await hashem.execute('logs'));return;}
  if(tail==='api/hashem/status'&&req.method==='GET'){json(res,200,await hashem.status());return;}
  if(tail==='api/hashem/action'&&req.method==='POST'){const v=await body(req);json(res,202,hashem.start(v.operation,v));return;}
  if(tail==='api/hashem/probe'&&req.method==='POST'){json(res,200,await hashem.execute('probe',await body(req)));return;}
  if(tail==='api/hashem/command'&&req.method==='POST'){const v=await body(req);if(!v.token)v.token=randomBytes(24).toString('hex');await hashem.execute('validate',v);json(res,200,hashem.command(v));return;}
  if(tail==='api/hashem/inbounds'&&req.method==='POST'){json(res,200,await createMatching(nativeClient(apiPort(req),base),await body(req)));return;}
  if(tail==='api/hashem/inbounds'&&req.method==='GET'){const result=await nativeClient(apiPort(req),base)('/admin/inbounds');json(res,200,{ports:[...new Set(result.inbounds.filter(i=>i.enabled!==false&&i.port&&(i.nodeId||'local')==='local').map(i=>i.port))]});return;}
  if(tail==='api/bot/install-result'&&req.method==='POST'){await body(req);json(res,200,bot.installResult());return;}
  if(tail==='api/bot/status'&&req.method==='GET'){json(res,200,await bot.status());return;}
