  if(tail==='api/bot/install'&&req.method==='POST'){const input=await body(req);const native=nativeClient(apiPort(req),base);const settings=await native('/admin/network-settings.json');const context=localContext(settings,apiPort(req),base,req.headers.host);json(res,202,bot.startInstall({...input,domain:context.botDomain},context));return;}
  if(tail==='api/bot/sync'&&req.method==='POST'){await body(req);const settings=await nativeClient(apiPort(req),base)('/admin/network-settings.json');json(res,200,await bot.syncLocal(localContext(settings,apiPort(req),base,req.headers.host)));return;}
