/* SPDX-License-Identifier: GPL-3.0-or-later */
(()=>{'use strict';const $=s=>document.querySelector(s),base=new URL('../api/ai/',location.href).pathname;
const theme=new URLSearchParams(location.search).get('theme');if(['dark','light'].includes(theme)){document.documentElement.dataset.theme=theme;document.dispatchEvent(new Event('alireza-theme'));}
let lang=initialLanguage(),current=null,busy=false,controller=null,cfg={},lastPrompt='',lastModel='',paint=0,historyOffset=0;
function initialLanguage(){try{if(parent!==window)return parent.document.documentElement.lang==='fa'||parent.document.documentElement.dir==='rtl'?'fa':'en';}catch{}const requested=new URLSearchParams(location.search).get('lang');if(['fa','en'].includes(requested))return requested;try{return localStorage.getItem('alireza-lang')==='en'?'en':'fa';}catch{return 'fa';}}
const strings={fa:{intro:'مشاور مدیریت VPN، تنظیمات و عیب‌یابی',settings:'تنظیمات Gemini',new:'＋ گفت‌وگوی جدید',history:'گفت‌وگوها',older:'نمایش پیام‌های قدیمی‌تر',privacy:'تاریخچهٔ این حساب از سایر حساب‌ها جداست.',prompt:'پیام شما',send:'ارسال',stop:'توقف',retry:'تلاش مجدد',summary:'پیش‌نمایش وضعیت برای ارسال',advisor:'AI فقط مشاور است؛ هیچ دستوری اجرا نمی‌کند. متن گفت‌وگو به Gemini ارسال می‌شود؛ رمز و کلید خصوصی وارد نکنید.',key:'کلید API',keynote:'خالی بماند تا کلید فعلی حفظ شود. کلید فقط روی سرور ذخیره می‌شود.',models:'دریافت مدل‌های سازگار',deletekey:'حذف کلید',model:'مدل',tokens:'حداکثر توکن پاسخ',rpm:'درخواست در دقیقه برای هر حساب',save:'ذخیره',copy:'کپی',remove:'حذف',ready:'آماده',generating:'در حال پاسخ…',saved:'تنظیمات ذخیره شد',confirm:'این مورد حذف شود؟',unknown:'عملیات ناموفق بود.',noHistory:'هنوز گفت‌وگویی نیست.',summaryConfirm:'این خلاصهٔ بدون نام، IP، رمز و کلید در کادر پیام اضافه شود؟',questions:['برای اینترنت ناپایدار چه پروتکلی مناسب است؟','خطای TLS را چطور بررسی کنم؟','چطور مشکل DNS را عیب‌یابی کنم؟']},en:{intro:'VPN management, configuration and troubleshooting advisor',settings:'Gemini settings',new:'＋ New conversation',history:'Conversations',older:'Load older messages',privacy:'History is isolated for this account.',prompt:'Your message',send:'Send',stop:'Stop',retry:'Retry',summary:'Preview status for sharing',advisor:'AI is an advisor and cannot execute commands. Conversation text is sent to Gemini; do not enter passwords or private keys.',key:'API key',keynote:'Leave blank to keep the current key. Stored only on the server.',models:'Load compatible models',deletekey:'Delete key',model:'Model',tokens:'Maximum response tokens',rpm:'Requests per minute per account',save:'Save',copy:'Copy',remove:'Delete',ready:'Ready',generating:'Generating…',saved:'Settings saved',confirm:'Delete this item?',unknown:'Operation failed.',noHistory:'No conversations yet.',summaryConfirm:'Append this summary without names, IPs, passwords or keys to the prompt?',questions:['Which protocol suits an unstable connection?','How can I troubleshoot TLS errors?','How should I diagnose DNS issues?']}};
const errors={AI_TIMEOUT:['مهلت اتصال به Gemini تمام شد؛ دوباره تلاش کنید.','Gemini request timed out. Retry.'],AI_SETTINGS_CHANGED:['کلید تغییر کرد؛ مدل‌ها را دوباره دریافت کنید.','API key changed. Reload models.'],AI_BAD_REQUEST:['درخواست توسط Gemini پذیرفته نشد؛ مدل و طول پاسخ را بررسی کنید.','Gemini rejected the request. Check model and response length.'],AI_PROVIDER_ERROR:['سرویس Gemini موقتاً پاسخ نداد.','Gemini service failed. Retry later.'],AI_KEY_MISSING:['ابتدا مدیر اصلی باید کلید Gemini را تنظیم کند.','The panel owner must configure a Gemini key.'],AI_KEY_DENIED:['کلید رد شد؛ محدودیت کلید و دسترسی API را بررسی کنید.','Key rejected. Check API restrictions and access.'],AI_QUOTA:['سهمیه یا نرخ مجاز Gemini تمام شده؛ بعداً تلاش کنید.','Gemini quota or rate limit reached. Retry later.'],AI_NETWORK:['اتصال به Gemini برقرار نشد؛ شبکهٔ سرور را بررسی کنید.','Could not connect to Gemini. Check server networking.'],AI_INVALID_RESPONSE:['پاسخ معتبر از Gemini دریافت نشد.','Invalid Gemini response.'],AI_MODEL_REQUIRED:['ابتدا مدل را در تنظیمات انتخاب کنید.','Select a model in settings first.'],AI_MODEL_UNAVAILABLE:['این مدل در دسترس نیست؛ فهرست مدل‌ها را تازه کنید.','Model unavailable. Refresh the model list.'],AI_STOPPED:['تولید پاسخ متوقف شد.','Generation stopped.'],AI_LOCAL_LIMIT:['حد مصرف تنظیم‌شده رسیده است؛ یک دقیقه صبر کنید.','Configured rate limit reached. Wait one minute.'],AI_BUSY:['برای این حساب یک پاسخ در حال تولید است.','A response is already generating for this account.'],AI_EMPTY_RESPONSE:['پاسخ متنی دریافت نشد.','No text response received.'],AI_BLOCKED:['پاسخ توسط ارائه‌دهنده مسدود شد.','Provider blocked the response.']};
const t=k=>strings[lang][k]||k,msg=code=>errors[code]?.[lang==='fa'?0:1]||code||t('unknown');
const el=(tag,text,cls)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;};
function notice(s=''){$('#notice').hidden=!s;$('#notice').textContent=s;}
async function api(path='',method='GET',data){const r=await fetch(base+path,{method,credentials:'same-origin',cache:'no-store',headers:data?{'content-type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok)throw Error(msg(j.code||j.error));return j;}
function translate(){document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));$('#lang').textContent=lang==='fa'?'English':'فارسی';$('#status').textContent=busy?t('generating'):cfg.hasKey?t('ready'):msg('AI_KEY_MISSING');$('#send').disabled=busy||!cfg.hasKey;$('#retry').disabled=busy||!lastPrompt||!cfg.hasKey;$('#suggestions').replaceChildren(...strings[lang].questions.map(q=>{const b=el('button',q);b.onclick=()=>{$('#prompt').value=q;$('#prompt').focus();};return b;}));}
function textContent(container,text){container.replaceChildren();const segments=text.split(/(```[\s\S]*?```)/g);for(const segment of segments){if(segment.startsWith('```')&&segment.endsWith('```')){const code=el('code',segment.slice(3,-3).replace(/^[^\n]*\n/,'')),pre=el('pre');pre.append(code);container.append(pre);}else{const p=el('span',segment);p.dir='auto';container.append(p);}}}
function bubble(role,text){const box=el('article',undefined,'message '+role),content=el('div',undefined,'text');content.dir='auto';textContent(content,text);box.append(content);if(role==='model'){const b=el('button',t('copy'),'copy');b.onclick=async()=>{try{if(!navigator.clipboard?.writeText)throw Error('CLIPBOARD_UNAVAILABLE');await navigator.clipboard.writeText(content.textContent);}catch{const selection=getSelection(),range=document.createRange();range.selectNodeContents(content);selection.removeAllRanges();selection.addRange(range);notice(lang==='fa'?'متن انتخاب شد؛ آن را کپی کنید.':'Text selected; copy it manually.');}};box.append(b);}$('#messages').append(box);return content;}
async function history(){const rows=await api('chats');$('#history').replaceChildren();if(!rows.length)$('#history').append(el('p',t('noHistory'),'hint'));for(const row of rows){const wrapper=el('div'),b=el('button',row.title),remove=el('button',t('remove'));b.onclick=()=>load(row.id);remove.onclick=async()=>{if(busy||!confirm(t('confirm')))return;try{await api('chats/'+row.id,'DELETE',{});if(current===row.id)newChat();await history();}catch(e){notice(e.message);}};wrapper.append(b,remove);$('#history').append(wrapper);}}
async function load(id){if(busy)return;try{const c=await api('chats/'+id);current=id;historyOffset=c.offset||0;$('#older').hidden=!historyOffset;$('#title').textContent=c.title;$('#messages').replaceChildren();c.messages.forEach(m=>bubble(m.role,m.text));lastPrompt=c.messages.findLast(m=>m.role==='user')?.text||'';notice();}catch(e){notice(e.message);}}
function newChat(){if(busy)return;current=null;historyOffset=0;$('#older').hidden=true;lastPrompt='';$('#title').textContent='AI';$('#messages').replaceChildren();notice();}
function setBusy(value){busy=value;$('#send').disabled=value;$('#retry').disabled=value||!lastPrompt;$('#new').disabled=value;$('#stop').hidden=!value;translate();}
async function send(retry=false){if(busy)return;const text=retry?lastPrompt:$('#prompt').value.trim();if(!text)return;notice();lastPrompt=text;lastModel=$('#model').value||cfg.model;controller=new AbortController();setBusy(true);if(!retry)bubble('user',text);else{const last=$('#messages').lastElementChild;if(last?.classList.contains('model'))last.remove();}const output=bubble('model','');let answer='';
try{const r=await fetch(base+'generate',{method:'POST',signal:controller.signal,headers:{'content-type':'application/json'},body:JSON.stringify({text,chatId:current,model:lastModel,retry})});if(!r.ok){const j=await r.json();throw Error(msg(j.code||j.error));}const decoder=new TextDecoder(),reader=r.body.getReader();let pending='';for(;;){const{value,done}=await reader.read();if(done)break;pending+=decoder.decode(value,{stream:true});let end;while((end=pending.search(/\r?\n\r?\n/))>=0){const separator=pending.slice(end).match(/^\r?\n\r?\n/)[0];const frame=pending.slice(0,end);pending=pending.slice(end+separator.length);const type=frame.match(/^event: (.*)\r?$/m)?.[1]?.trim(),raw=frame.match(/^data: (.*)\r?$/m)?.[1];if(!raw)continue;const j=JSON.parse(raw);if(type==='chat'){current=j.id;$('#title').textContent=j.title;}if(type==='text'){answer+=j.text;if(!paint)paint=requestAnimationFrame(()=>{paint=0;textContent(output,answer);$('#messages').scrollTop=$('#messages').scrollHeight;});}if(type==='error')notice(msg(j.code));if(type==='done'&&j.finishReason==='MAX_TOKENS')notice(lang==='fa'?'پاسخ به حد طول تنظیم‌شده رسید.':'Response reached the configured token limit.');}}
textContent(output,answer);$('#prompt').value='';await history();}catch(e){notice(e.name==='AbortError'?msg('AI_STOPPED'):e.message);}finally{if(paint){cancelAnimationFrame(paint);paint=0;}textContent(output,answer);setBusy(false);controller=null;}}
$('#older').onclick=async()=>{if(busy||!current||!historyOffset)return;try{const c=await api('chats/'+current+'/before/'+historyOffset);for(const m of c.messages.slice().reverse()){const content=bubble(m.role,m.text);$('#messages').insertBefore(content.parentElement,$('#messages').firstElementChild);}historyOffset=c.offset;$('#older').hidden=!historyOffset;}catch(e){notice(e.message);}};
$('#composer').onsubmit=e=>{e.preventDefault();send();};$('#stop').onclick=async()=>{controller?.abort();await api('stop','POST',{}).catch(()=>{});};$('#retry').onclick=()=>send(true);$('#new').onclick=newChat;$('#lang').onclick=()=>{lang=lang==='fa'?'en':'fa';try{localStorage.setItem('alireza-lang',lang);}catch{}translate();history().catch(e=>notice(e.message));};$('#close').onclick=()=>$('#config').close();$('#settings').onclick=()=>$('#config').showModal();
$('#listmodels').onclick=async()=>{const b=$('#listmodels');b.disabled=true;try{if(cfg.canManage&&$('#key').value.trim()){cfg=await api('settings','PUT',{apiKey:$('#key').value.trim()});$('#key').value='';translate();}const rows=await api('models');$('#model').replaceChildren(...rows.map(m=>{const o=el('option',m.displayName+' · '+m.name);o.value=m.name;return o;}));if(rows.some(m=>m.name===cfg.model))$('#model').value=cfg.model;if(!rows.length)throw Error(msg('AI_MODEL_UNAVAILABLE'));if(cfg.canManage){cfg=await api('settings','PUT',{model:$('#model').value});translate();}$('#configmessage').textContent=lang==='fa'?'مدل‌ها از API رسمی دریافت شدند.':'Models loaded from the official API.';}catch(e){$('#configmessage').textContent=e.message;}finally{b.disabled=false;}};
$('#configform').onsubmit=async e=>{e.preventDefault();$('#saveconfig').disabled=true;try{cfg=await api('settings','PUT',{apiKey:$('#key').value,model:$('#model').value,maxOutputTokens:+$('#tokens').value,requestsPerMinute:+$('#rpm').value});$('#key').value='';$('#configmessage').textContent=t('saved');translate();}catch(e){$('#configmessage').textContent=e.message;}finally{$('#saveconfig').disabled=false;}};
$('#deletekey').onclick=async()=>{if(!confirm(t('confirm')))return;try{cfg=await api('settings','PUT',{deleteKey:true});$('#key').value='';translate();}catch(e){$('#configmessage').textContent=e.message;}};
$('#summary').onclick=async()=>{try{const summary=await api('summary');const text=JSON.stringify(summary,null,2);if(confirm(t('summaryConfirm')+'\n\n'+text))$('#prompt').value+='\n'+text;}catch(e){notice(e.message);}};
try{if(parent!==window)new MutationObserver(()=>{const next=initialLanguage();if(next!==lang){lang=next;translate();history().catch(e=>notice(e.message));}}).observe(parent.document.documentElement,{attributes:true,attributeFilter:['lang','dir']});}catch{}
(async()=>{translate();try{cfg=await api('settings');$('#tokens').value=cfg.maxOutputTokens;$('#rpm').value=cfg.requestsPerMinute;if(cfg.model){const o=el('option',cfg.model);o.value=cfg.model;$('#model').append(o);}for(const id of ['keylabel','deletekey','saveconfig'])$('#'+id).hidden=!cfg.canManage;$('#tokens').disabled=!cfg.canManage;$('#rpm').disabled=!cfg.canManage;$('#summary').hidden=!cfg.canManage;translate();await history();}catch(e){notice(e.message);}})();
})();
