 const advancedFlags=[['isDisabled','غیرفعال‌کردن همین میزبان','Disable this host'],['isHidden','پنهان در نمای پیش‌فرض میزبان‌ها','Hide from default hosts overview'],['overrideSniFromAddress','SNI از نشانی میزبان','Use endpoint address as SNI'],['keepSniBlank','عدم بازنویسی SNI پایه','Keep base SNI'],['shuffleHost','درهم‌آمیختن ترتیب میزبان‌های انتخاب‌شده','Shuffle selected hosts']];
 const jsonFields=[['muxParams','Multiplexing · Xray'],['sockoptParams','Socket options · Xray'],['finalMask','FinalMask · Xray']];
 function advanced(p){const text=advancedTexts.map(([k,f,e])=>`<div class="field"><label for="azh-${k}">${esc(tr(f,e))}</label><input class="input" id="azh-${k}" name="${k}" dir="ltr" value="${esc(Array.isArray(p[k])?p[k].join(','):p[k])}"></div>`).join('');const selects=[['security',tr('امنیت خروجی اشتراک','Subscription security'),['same','tls','none','reality']],['allowInsecure',tr('اعتبارسنجی گواهی','Certificate verification'),['inherit','verify','insecure']],['mihomoIpVersion','Mihomo IP version',['','dual','ipv4','ipv6','ipv4-prefer','ipv6-prefer']]].map(([k,label,values])=>`<div class="field"><label for="azh-${k}">${esc(label)}</label><select class="input" dir="ltr" name="${k}" id="azh-${k}">${values.map(v=>`<option ${v===(k==='allowInsecure'?p[k]===true?'insecure':p[k]===false?'verify':'inherit':p[k]|| (k==='security'?'same':''))?'selected':''} value="${esc(v)}">${esc(v||'default')}</option>`).join('')}</select></div>`).join('');return `<details class="prof-sec" open><summary>${esc(tr('امنیت، انتشار و تنظیمات پیشرفته','Security, publishing and advanced settings'))}</summary><div class="azm-grid">${selects+text}</div>${advancedFlags.map(([k,f,e])=>`<label class="inb-multi-row"><input type="checkbox" name="${k}" ${p[k]?'checked':''}><span>${esc(tr(f,e))}</span></label>`).join('')}<div class="prof-sec"><strong>${esc(tr('حذف از فرمت‌های اشتراک','Exclude from subscription formats'))}</strong>${['raw','json','clash','singbox'].map(v=>`<label class="inb-multi-row"><input type="checkbox" name="excludeFromSubTypes" value="${v}" ${p.excludeFromSubTypes?.includes(v)?'checked':''}> ${v}</label>`).join('')}</div>${jsonFields.map(([k,label])=>`<div class="field"><label for="azh-${k}">${esc(label)}</label><textarea class="input" name="${k}" id="azh-${k}" dir="ltr" rows="4" spellcheck="false">${esc(p[k]?typeof p[k]==='string'?p[k]:JSON.stringify(p[k],null,2):'')}</textarea></div>`).join('')}<p class="az-manual-note">${esc(tr('این گزینه‌ها خروجی کلاینت را تغییر می‌دهند؛ شنونده و کاربران سرور تغییر نمی‌کنند. Mux، Sockopt و FinalMask برای Xray هستند. پین گواهی و FinalMask برای Sing-box تبدیل معادل ندارند؛ آن فرمت را مستثنا کنید.','These options change client exports, not server listeners or accounts. Mux, Sockopt and FinalMask target Xray. Exclude Sing-box when using certificate pins or FinalMask: those settings have no equivalent conversion.'))}</p></details>`;}
 function readAdvanced(f,data){for(const[k]of advancedTexts){const value=f.elements[k].value.trim();if(['alpn','pinnedPeerCertSha256','tags','nodeGuids'].includes(k))data[k]=value.split(',').map(v=>v.trim()).filter(Boolean);else data[k]=value;}for(const[k]of advancedFlags)data[k]=f.elements[k].checked;if(f.elements.allowInsecure.value==='inherit')delete data.allowInsecure;else data.allowInsecure=f.elements.allowInsecure.value==='insecure';data.security=f.elements.security.value;data.mihomoIpVersion=f.elements.mihomoIpVersion.value;data.excludeFromSubTypes=[...f.querySelectorAll('[name=excludeFromSubTypes]:checked')].map(x=>x.value);for(const[k]of jsonFields){const value=f.elements[k].value.trim();if(!value){delete data[k];continue;}let parsed;try{parsed=JSON.parse(value);}catch{throw Error(k+tr(' باید JSON معتبر باشد',' must contain valid JSON'));}if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error(k+tr(' باید یک شیء JSON باشد',' must be a JSON object'));data[k]=parsed;}if(data.overrideSniFromAddress&&data.keepSniBlank)throw Error(tr('فقط یکی از گزینه‌های عدم بازنویسی SNI پایه یا SNI از نشانی را انتخاب کنید','Choose either base SNI or SNI from address'));if(data.tags.some(v=>!/^[A-Z0-9_:]{1,36}$/.test(v))||data.tags.length>10)throw Error(tr('برچسب‌ها باید حروف بزرگ انگلیسی/عدد و _ : باشند؛ حداکثر ۱۰ مورد','Use uppercase tags with digits, _ or :; maximum 10'));if((data.pinnedPeerCertSha256.length||data.finalMask||data.verifyPeerCertByName)&&!data.excludeFromSubTypes.includes('singbox'))throw Error(tr('برای این گزینه‌ها فرمت Sing-box را مستثنا کنید','Exclude Sing-box for these host options'));}
 // Native inline profile forms know only the original seven fields. Preserve
 // advanced metadata on ordinary inbound edits and direct profile edits here.
 if(typeof api==='function'){const originalAPI=api;const basicKeys=['name','address','port','sni','hostHeader','path','serviceName'];const shape=p=>JSON.stringify(basicKeys.map(k=>p?.[k]??''));api=async function(route,options){const v=options?.body;if(route==='/admin/inbounds'&&options?.method==='POST'&&v?.action==='update'&&v.inbound?.id){const current=(await originalAPI('/admin/inbounds')).inbounds?.find(i=>i.id===v.inbound.id);if(current){const old=current.profiles||[],next=v.inbound.profiles||old,advanced=old.some(p=>Object.keys(p).some(k=>!basicKeys.includes(k)));if(advanced&&(old.length!==next.length||old.some((p,i)=>shape(p)!==shape(next[i]))))throw Error(tr('میزبان پیشرفته را از بخش میزبان‌ها ویرایش کنید؛ تنظیمات فعلی حفظ شد.','Edit advanced hosts in Hosts. Existing settings were retained.'));const profiles=next.map((p,i)=>old[i]&&shape(p)===shape(old[i])?{...old[i],...p}:p);options={...options,body:{...v,inbound:{...v.inbound,profiles}}};}}return originalAPI(route,options);};}

 let pending=false;
 const U=window.AlirezaUI;
 async function hostAPI(method='GET',value){const r=await fetch((window.__NOVA_BASE__||'')+'/alireza/api/hosts',{method,credentials:'same-origin',cache:'no-store',headers:value?{'content-type':'application/json'}:{},body:value?JSON.stringify(value):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'HOST_FAILED');return data;}
 const gid=()=> 'host-'+[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,'0')).join('');
 function collect(rows){const map=new Map();for(const i of rows.filter(supported))for(const[p,index]of(i.profiles||[]).map((p,index)=>[p,index])){const key=p.azHostGroup||i.id+':'+index;if(!map.has(key))map.set(key,{key,records:[]});map.get(key).records.push({inbound:i,index,p});}return [...map.values()];}
 window.alirezaHosts=async()=>{if(typeof isOwner!=='function'||!isOwner()||!U)return;const page=U.page(tr('میزبان‌ها','Hosts'),`<div class="az-hosts"><div class="az-host-summary" data-summary></div><div class="az-manual-actions"><button class="btn primary" data-add>${esc(tr('افزودن میزبان','Add host'))}</button><button class="btn" data-refresh>${esc(tr('تازه‌سازی','Refresh'))}</button><input class="input" data-search placeholder="${esc(tr('جست‌وجو','Search'))}"></div><label><input type="checkbox" data-hidden> ${esc(tr('نمایش پنهان‌ها','Show hidden hosts'))}</label><div class="az-manual-actions">${[['enable','فعال','Enable'],['disable','غیرفعال','Disable'],['delete','حذف','Delete']].map(([k,f,e])=>`<button class="btn" data-bulk="${k}" disabled>${esc(tr(f,e))}</button>`).join('')}</div><div class="field-err show" data-error role="alert"></div><div class="az-scroll"><table><thead><tr>${['',tr('عملیات','Actions'),tr('فعال','Enabled'),tr('نام','Remark'),tr('نشانی','Endpoint'),tr('اینباند','Inbound'),tr('امنیت','Security'),tr('برچسب‌ها','Tags')].map(t=>'<th>'+esc(t)+'</th>').join('')}</tr></thead><tbody data-rows></tbody></table></div></div>`);if(!page)return;const root=page.querySelector('.az-hosts'),error=root.querySelector('[data-error]'),tbody=root.querySelector('[data-rows]');let rows=[],groups=[],generation=0;const selected=new Set();
 function select(){root.querySelectorAll('[data-bulk]').forEach(b=>b.disabled=!selected.size||pending);}
 async function commit(next){if(pending)throw Error(tr('عملیات دیگری در جریان است','Another operation is running'));pending=true;select();try{const updates=rows.filter(i=>JSON.stringify(next[i.id]??i.profiles??[])!==JSON.stringify(i.profiles||[])).map(i=>({inboundId:i.id,expected:JSON.stringify(i.profiles||[]),profiles:next[i.id]}));if(updates.length)await hostAPI('PUT',{updates});await refresh();}finally{pending=false;select();}}
 function copyState(){return Object.fromEntries(rows.map(i=>[i.id,structuredClone(i.profiles||[])]));}
 function graph(form){for(const[name,defs]of[['muxParams',[['enabled','checkbox'],['concurrency','number'],['xudpConcurrency','number']]],['sockoptParams',[['tcpFastOpen','checkbox'],['tcpKeepAliveIdle','number'],['tcpKeepAliveInterval','number'],['tcpMaxSeg','number'],['interface','text']]]]){const source=form.elements[name];let data;try{data=JSON.parse(source.value||'{}');}catch{data={};}const box=document.createElement('div');box.className='prof-sec';box.innerHTML='<strong>'+name+'</strong><label class="inb-multi-row"><input type="checkbox" data-override '+(source.value?'checked':'')+'> '+esc(tr('تنظیم اختصاصی','Custom override'))+'</label><div class="az-grid">'+defs.map(([k,type])=>'<label class="field">'+k+'<input class="input" data-key="'+k+'" type="'+type+'" '+(type==='checkbox'?(data[k]?'checked':''):'value="'+esc(data[k]??'')+'"')+(type==='number'?' min="0" max="65535"':'')+'></label>').join('')+'</div>';const sync=()=>{if(!box.querySelector('[data-override]').checked){source.value='';return;}let o;try{o=JSON.parse(source.value||'{}');}catch{o={};}for(const input of box.querySelectorAll('[data-key]')){if(input.type==='checkbox')o[input.dataset.key]=input.checked;else if(input.value!=='')o[input.dataset.key]=input.type==='number'?Number(input.value):input.value;else delete o[input.dataset.key];}source.value=JSON.stringify(o,null,2);};box.oninput=sync;source.closest('.field').before(box);}}
 function edit(group){const p=group?.records[0]?.p||{},eligible=rows.filter(supported),ids=new Set(group?.records.map(r=>r.inbound.id)||[]),addresses=[...new Set(group?.records.map(r=>r.p.address||'').filter(Boolean)||[])];if(!eligible.length){error.textContent=tr('ابتدا یک اینباند سازگار بسازید','Create a compatible inbound first');return;}
 const m=U.wide(openModal({title:tr('میزبان','Host'),body:'<form id="azh-edit"><div data-main class="az-grid"><div class="field"><label>'+esc(tr('نام','Remark'))+'</label><input class="input" name="name" value="'+esc(p.azHostName||p.name)+'"></div><div class="field"><label>'+esc(tr('دامنه یا IP؛ هر نشانی یک سطر','Domain or IP; one per line'))+'</label><textarea class="input" name="addresses" dir="ltr" rows="4">'+esc(addresses.join('\n'))+'</textarea></div>'+fields.filter(([k])=>!['name','address'].includes(k)).map(([k,f,e])=>'<label class="field">'+esc(tr(f,e))+'<input class="input" name="'+k+'" dir="ltr" value="'+esc(p[k])+'" '+(k==='port'?'type="number" min="1" max="65535"':'')+'></label>').join('')+'<div class="prof-sec">'+eligible.map(i=>'<label class="inb-multi-row"><input name="inbound" type="checkbox" value="'+esc(i.id)+'" '+(ids.has(i.id)?'checked':'')+'> '+esc((i.remark||i.protocol)+' · '+(i.port||tr('پورت مشترک پنل','Shared panel port')))+'</label>').join('')+'</div></div>'+advanced(p)+'<div class="field-err show" data-form-error role="alert"></div></form>',okLabel:tr('ذخیره','Save'),onOk:async(close,lock)=>{const f=m.querySelector('form'),err=f.querySelector('[data-form-error]');if(!f.reportValidity()||pending)return;try{const chosen=new Set([...f.querySelectorAll('[name=inbound]:checked')].map(e=>e.value)),addresses=[...new Set(f.elements.addresses.value.split(/\s+/).filter(Boolean))];if(!chosen.size)throw Error(tr('حداقل یک اینباند انتخاب کنید','Select at least one inbound'));if(addresses.some(v=>/[/@?#\s]/.test(v)||v.includes('://')))throw Error(tr('دامنه یا IP بدون مسیر و پورت وارد کنید','Enter domains or IPs without paths or ports'));if(!addresses.length)addresses.push('');const data={...p};for(const[k]of fields){if(k==='address')continue;const v=f.elements[k].value.trim();if(v)data[k]=k==='port'?Number(v):v;else delete data[k];}readAdvanced(f,data);const key=p.azHostGroup||gid();data.azHostGroup=key;data.azHostName=data.name||'';const next=copyState();if(group)for(const i of rows)next[i.id]=next[i.id].filter((p,n)=>!group.records.some(r=>r.inbound.id===i.id&&r.index===n));for(const i of eligible.filter(i=>chosen.has(i.id))){if(next[i.id].length+addresses.length>64)throw Error(tr('حداکثر 64 میزبان برای هر اینباند','Maximum 64 hosts per inbound'));next[i.id].push(...addresses.map(address=>({...data,...(address?{address}:{address:''})})));}lock(true);await commit(next);close();}catch(e){err.textContent=e.message;lock(false);}}}));const f=m.querySelector('form');graph(f);const details=f.querySelector('details'),main=f.querySelector('[data-main]'),sec=document.createElement('div'),adv=document.createElement('div'),mih=document.createElement('div');for(const n of [...details.children]){if(n.tagName==='SUMMARY')continue;if(n.classList.contains('azm-grid')){for(const field of [...n.children]){const name=field.querySelector('[name]')?.name;(name==='mihomoIpVersion'?mih:sec).append(field);}n.remove();}else adv.append(n);}details.remove();U.tabs(f,[['basic',tr('مشخصات','Basic'),[main]],['security',tr('امنیت','Security'),[sec]],['advanced',tr('پیشرفته','Advanced'),[adv]],['mihomo','Mihomo',[mih]]]);}
 async function operate(action,chosen){if(pending)return;if(['delete','remove'].includes(action)&&!confirm(tr('میزبان‌های انتخاب‌شده حذف شوند؟ کاربران و اینباندها حفظ می‌شوند.','Delete selected hosts? Accounts and inbounds are retained.')))return;try{const next=copyState();if(action==='up'||action==='down'){const index=groups.indexOf(chosen[0]),target=index+(action==='up'?-1:1);if(target<0||target>=groups.length)return;const order=groups.map(g=>g.key);[order[index],order[target]]=[order[target],order[index]];for(const i of rows)next[i.id]=next[i.id].map((p,n)=>({p,rank:order.indexOf(p.azHostGroup||i.id+':'+n)})).sort((a,b)=>a.rank-b.rank).map(x=>x.p);}else{const copies=new Map(chosen.map(g=>[g.key,gid()]));for(const i of rows){const additions=[];next[i.id]=(i.profiles||[]).flatMap((p,index)=>{const g=chosen.find(g=>g.records.some(r=>r.inbound.id===i.id&&r.index===index));if(!g)return [p];if(action==='delete'||action==='remove')return [];if(action==='copy'){additions.push({...p,azHostGroup:copies.get(g.key),name:(p.name||p.address||'')+' (copy)',azHostName:(p.azHostName||p.name||'')+' (copy)'});return [p];}return [{...p,isDisabled:action==='disable'}];});next[i.id].push(...additions);}}await commit(next);}catch(e){error.textContent=e.message;}}
 function draw(){tbody.replaceChildren();const q=root.querySelector('[data-search]').value.toLowerCase(),visible=groups.filter(g=>(root.querySelector('[data-hidden]').checked||g.records.some(r=>!r.p.isHidden))&&JSON.stringify(g.records.map(r=>[r.p,r.inbound.remark])).toLowerCase().includes(q));root.querySelector('[data-summary]').innerHTML=[[tr('همه','Total'),groups.length],[tr('فعال','Enabled'),groups.filter(g=>g.records.some(r=>!r.p.isDisabled)).length],[tr('غیرفعال','Disabled'),groups.filter(g=>g.records.every(r=>r.p.isDisabled)).length]].map(([k,v])=>'<div>'+esc(k)+' <strong>'+v+'</strong></div>').join('');for(const g of visible){const p=g.records[0].p,row=document.createElement('tr');const cell=()=>{const td=document.createElement('td');row.append(td);return td;};const box=document.createElement('input');box.type='checkbox';box.checked=selected.has(g.key);box.setAttribute('aria-label',tr('انتخاب میزبان','Select host'));box.onchange=()=>{if(box.checked)selected.add(g.key);else selected.delete(g.key);select();};cell().append(box);const actions=cell();actions.className='az-manual-actions';for(const[k,f,e]of[['up','↑','↑'],['down','↓','↓'],['edit','ویرایش','Edit'],['copy','تکثیر','Duplicate'],['delete','حذف','Delete']]){const b=document.createElement('button');b.className='btn sm';b.textContent=tr(f,e);b.title=k;b.disabled=k==='up'?groups.indexOf(g)===0:k==='down'?groups.indexOf(g)===groups.length-1:false;b.onclick=()=>k==='edit'?edit(g):operate(k,[g]);actions.append(b);}const enabled=document.createElement('input');enabled.type='checkbox';enabled.checked=g.records.some(r=>!r.p.isDisabled);enabled.setAttribute('aria-label',tr('فعال','Enabled'));enabled.onchange=()=>operate(enabled.checked?'enable':'disable',[g]);cell().append(enabled);cell().textContent=p.azHostName||p.name||'—';cell().textContent=[...new Set(g.records.map(r=>r.p.address||tr('پیش‌فرض','Default')))].join(', ');cell().textContent=[...new Set(g.records.map(r=>r.inbound.remark||r.inbound.protocol))].join(', ');cell().textContent=p.security||'same';cell().textContent=(p.tags||[]).join(', ');tbody.append(row);}if(!visible.length){const r=document.createElement('tr'),c=document.createElement('td');c.colSpan=8;c.textContent=tr('میزبانی پیدا نشد','No hosts found');r.append(c);tbody.append(r);}}
 async function refresh(){const id=++generation;error.textContent='';try{const result=await hostAPI();if(id!==generation||!page.isConnected)return;rows=result.inbounds||[];groups=collect(rows);selected.clear();select();draw();}catch(e){error.textContent=e.message;}}
 root.querySelector('[data-add]').onclick=()=>edit(null);root.querySelector('[data-refresh]').onclick=refresh;root.querySelector('[data-search]').oninput=draw;root.querySelector('[data-hidden]').onchange=draw;for(const b of root.querySelectorAll('[data-bulk]'))b.onclick=()=>operate(b.dataset.bulk,groups.filter(g=>selected.has(g.key)));await refresh();};
 dispatchEvent(new Event('alireza-modules-ready'));
})();
