        echo -e "[${GREEN}OK${NC}]     Backhaul Server Service (listening on :${BIND_PORT}, transport: ${TRANSPORT})"
    else
        echo -e "[${RED}FAILED${NC}] Backhaul Server Service (${BH_ERR})"
    fi

    if [[ "${GRE_SKIP_PANEL:-0}" != "1" ]]; then
