 card.addEventListener('click',async e=>{const b=e.target.closest('[data-hashem-action]');if(!b)return;const a=b.dataset.hashemAction;if(a==='refresh'){await refresh();return;}if(a==='setup'){setup();return;}if(a==='logs'){try{const r=await api('logs');openModal({title:tr('لاگ‌های Hashem','Hashem logs'),body:'<pre class="mono" dir="ltr">'+esc(r.logs||tr('لاگی وجود ندارد','No logs available'))+'</pre>',okLabel:tr('بستن','Close'),onOk:close=>close()});}catch(e){error.textContent=e.message;}return;}if(a==='inbounds'){if(state.configuration?.role!=='foreign'){error.textContent=tr('ساخت اینباند متناظر روی سمت Foreign انجام می‌شود.','Matching listeners are created on the Foreign endpoint.');return;}const modal=openModal({title:tr('اینباندهای متناظر تانل','Matching tunnel inbounds'),body:'<form data-match><div class="azm-grid">'+field('ports',tr('پورت‌های محلی اینباند','Local inbound ports'),(state.configuration.ports||[]).join(','))+field('host',tr('نشانی اشتراک سمت Iran','Iran subscription address'),state.configuration.remotePub)+field('path','WebSocket path','/@alirezaserver')+'</div><p class="az-manual-note">'+esc(tr('VLESS + WebSocket بدون TLS ساخته می‌شود. هیچ حسابی خودکار مجاز نمی‌شود؛ بعد از ساخت، کاربران مجاز را در بخش اینباند انتخاب کنید. این گزینه فقط داخل تونل امن مناسب است. اینباندهای قبلی بازنویسی نمی‌شوند.','Creates VLESS + WebSocket without TLS. No users are authorized automatically; assign users in Inbounds afterwards. Use only inside a trusted tunnel. Existing inbounds are never replaced.'))+'</p><div class="field-err show" data-match-error></div></form>',okLabel:tr('ساخت','Create'),onOk:async(close,lock)=>{if(!confirm(tr('این شنونده‌ها بدون TLS و بدون تخصیص کاربر ساخته شوند؟','Create these listeners without TLS and without user assignment?')))return;lock(true);try{const f=modal.querySelector('form');await api('inbounds','POST',{ports:f.elements.ports.value,host:f.elements.host.value,path:f.elements.path.value,confirm:true});close();await refresh();}catch