let kv,auth,cached;
async function session(){if(!auth){const dir=process.env.ALIREZA_NOVA_DIR||'/opt/nova-node-agent';const k=await import(pathToFileURL(dir+'/src/kv/sqlite.mjs'));auth=await import(pathToFileURL(dir+'/src/auth.mjs'));kv=k.openKv(process.env.NOVA_DB||'/var/lib/nova/nova.db');}if(!cached||Date.now()-cached.at>300000){const s=await auth.makeSession(kv,{userAgent:'alirezabot-service'});cached={at:Date.now(),cookie:s.name+'='+s.value};}return cached.cookie;}
