// Additive repair for the web product editor. Existing plan values/types are retained; invalid NULL status gets the normal active default.
return static function (PDO $pdo, $schema = null): void {
    $lock = 'alirezabot.product-schema.v1';
    $stmt = $pdo->prepare('SELECT GET_LOCK(?, 15)');
    $stmt->execute([$lock]);
    if ((int) $stmt->fetchColumn() !== 1) {
        throw new RuntimeException('BOT_PRODUCT_SCHEMA_BUSY');
    }
