        if (!$table) {
            throw new RuntimeException('BOT_PRODUCT_TABLE_MISSING');
        }
        $read = $pdo->query("SELECT COLUMN_NAME, COLUMN_DEFAULT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='product'");
        $columns = [];
        foreach ($read->fetchAll(PDO::FETCH_ASSOC) as $column) $columns[strtolower($column['COLUMN_NAME'])] = $column;
        // Additive opt-in: old plans remain disabled.
        if (!isset($columns['geo_exits'])) {
            $pdo->exec('ALTER TABLE `product` ADD COLUMN `geo_exits` TINYINT UNSIGNED NOT NULL DEFAULT 0');
        }
        // Zero is the existing UI's unlimited/default IP count. Never UPDATE old columns.
        if (!isset($columns['limitip'])) {
            $pdo->exec('ALTER TABLE `product` ADD COLUMN `limitip` INT UNSIGNED NOT NULL DEFAULT 0');
        }
        // The initial CREATE definition also omitted this column, while bot queries use it.
        if (!isset($columns['status_product'])) {
            $pdo->exec("ALTER TABLE `product` ADD COLUMN `status_product` VARCHAR(20) NOT NULL DEFAULT 'active'");
        } elseif ($columns['status_product']['COLUMN_DEFAULT'] === null || strtoupper((string)$columns['status_product']['COLUMN_DEFAULT']) === 'NULL') {
