// Shared in-process scheduler: no per-reseller daemon, port or PHP pool.
import fs from 'node:fs';import {seal,unseal} from './vault.mjs';import * as shop from './shop.mjs';
const summary=p=>p.kind==='admin'&&p.role!=='reseller'?'دسترسی مدیریتی بدون سهمیه حجمی':(p.quotaBytes/1073741824)+' GB · '+p.days+' روز';
const fail=c=>Object.assign(Error(c),{status:502,code:c});
export async function telegram(token,method,payload){let r;try{r=await fetch('https://api.telegram.org/bot'+token+'/'+method,{method:'POST',redirect:'error',signal:AbortSignal.timeout(15000),headers:{'content-type':'application/json'},body:JSON.stringify(payload)});}catch{throw fail('SHOP_TELEGRAM_NETWORK');}if(!r.ok)throw fail(r.status===429?'SHOP_TELEGRAM_RATE_LIMIT':'SHOP_TELEGRAM_REJECTED');const text=await r.text();if(text.length>2097152)throw fail('SHOP_TELEGRAM_RESPONSE_SIZE');let j;try{j=JSON.parse(text);}catch{throw fail('SHOP_TELEGRAM_INVALID_RESPONSE');}if(!j.ok)throw fail('SHOP_TELEGRAM_REJECTED');return j.result;}
export async function handleUpdate(owner,update,context,apiTelegram=telegram){const message=update.message||update.callback_query?.message,actor=update.message?.from||update.callback_query?.from;if(!message||message.chat?.type!=='private'||String(actor?.id)!==String(message.chat.id))return;const buyer=String(actor.id),data=update.callback_query?.data||'',text=String(update.message?.text||''),seq=String(update.update_id),cfg=shop.config(owner,true),send=(body,keyboard)=>apiTelegram(cfg.token,'sendMessage',{chat_id:buyer,text:body,...(keyboard?{reply_markup:{inline_keyboard:keyboard}}:{})});if(update._shopEpoch&&update._shopEpoch!==cfg.epoch)return;if(update.callback_query)await apiTelegram(cfg.token,'answerCallbackQuery',{callback_query_id:update.callback_query.id}).catch(()=>{});
 if(text==='/start'||text==='/plans'||data==='shop:plans'||data.startsWith('shop:p:')){shop.database().prepare('DELETE FROM selections WHERE owner=? AND buyer=?').run(owner,buyer);const page=data.startsWith('shop:p:')?Number(data.slice(7)):0;if(!Number.isSafeInteger(page)||page<0)return;const rows=shop.plans(owner,{active:true,offset:page*20,limit:20}),plans=rows.slice(0,20);const navigation=[];if(page)navigation.push({text:'←',callback_data:'shop:p:'+(page-1)});if(rows.length>20)navigation.push({text:'→',callback_data:'shop:p:'+(page+1)});await send('فروشگاه اختصاصی / Your store\nاعتبار: '+shop.balance(owner,buyer)+'\nپلن موردنظر را انتخاب کنید.\n/wallet · /orders',[...plans.map(p=>[{text:p.name+' · '+(p.pricing==='volume'?p.unitPrice+' / GB':p.price),callback_data:'shop:q:'+p.id}]),...(navigation.length?[navigation]:[])]);return;}
 if(data.startsWith('shop:q:')){const plan=shop.findPlan(owner,data.slice(7));if(plan?.pricing==='volume'){shop.database().prepare('INSERT INTO selections VALUES(?,?,?,?) ON CONFLICT(owner,buyer) DO UPDATE SET plan=excluded.plan,expires=excluded.expires').run(owner,buyer,plan.id,Date.now()+900000);await send('حجم دلخواه را به GB بفرستید.\nمحدوده '+plan.minGB+' تا '+plan.maxGB+' GB · قیمت هر GB: '+plan.unitPrice,[...[10,50,100].filter(x=>x>=plan.minGB&&x<=plan.maxGB).map(x=>[{text:x+' GB',callback_data:'shop:v:'+plan.id+':'+x}])]);return;}const q=shop.quote(owner,buyer,data.slice(7));await send(q.plan.name+'\n'+summary(q.plan)+'\nقیمت: '+q.plan.price,[[{text:'تأیید خرید / Confirm',callback_data:'shop:b:'+q.id}]]);return;}
 const selected=shop.database().prepare('SELECT * FROM selections WHERE owner=? AND buyer=? AND expires>?').get(owner,buyer,Date.now());
 if(data.startsWith('shop:v:')||(/^\d+$/.test(text)&&selected)){const parts=data.split(':');const planId=data.startsWith('shop:v:')?parts[2]:selected.plan,units=data.startsWith('shop:v:')?Number(parts[3]):Number(text);const q=shop.quote(owner,buyer,planId,units);shop.database().prepare('DELETE FROM selections WHERE owner=? AND buyer=?').run(owner,buyer);await send(q.plan.name+' · '+q.plan.units+' GB · '+q.plan.price,[[{text:'تأیید خرید / Confirm',callback_data:'shop:b:'+q.id}]]);return;}
 if(text.startsWith('/volume ')){const m=text.match(/^\/volume\s+([a-f0-9]{32})\s+(\d+)$/);if(!m){await send('/volume plan-id GB');return;}const q=shop.quote(owner,buyer,m[1],Number(m[2]));await send(q.plan.name+' · '+q.plan.units+' GB · '+q.plan.price,[[{text:'تأیید خرید / Confirm',callback_data:'shop:b:'+q.id}]]);return;}
 if(data.startsWith('shop:b:')){const qid=data.slice(7);try{const r=await shop.purchase(owner,buyer,qid,context.native(owner),{panelURL:await context.panelURL()});if(r.status==='ready')shop.queueMessage(owner,buyer,'سفارش / Order '+r.id+'\n'+Object.entries(r.credentials).filter(([k])=>!['adminId','configs'].includes(k)).map(([k,v])=>k+': '+v).join('\n'),'order:'+r.id);else await send('سفارش ثبت شده و در حال بررسی است. دوباره از همین دکمه وضعیت را بررسی کنید.');}catch(e){await send(e.code==='SHOP_INSUFFICIENT_BALANCE'?'اعتبار کافی نیست. /wallet را بزنید.':'سفارش در انتظار بررسی؛ دوباره از همین دکمه تلاش کنید. '+String(e.code||e.message).slice(0,150));}return;}
 if(text==='/wallet'){await send('اعتبار / Balance: '+shop.balance(owner,buyer)+'\n'+(cfg.paymentInstructions||'برای شارژ با فروشنده تماس بگیرید.')+'\nپس از پرداخت: /topup مبلغ شماره‌پیگیری\nرسید پس از تأیید فروشنده شارژ می‌شود.');return;}
