// SPDX-License-Identifier: GPL-3.0-or-later
// Customer management is bound to the paid order AND Telegram buyer identity.
import{randomBytes}from'node:crypto';import * as shop from'./shop.mjs';import{seal,unseal}from'./vault.mjs';
const locks=new Map(),fail=(m,s=400)=>Object.assign(Error(m),{status:s,code:m});
