// SPDX-License-Identifier: GPL-3.0-or-later
// Full Mirza instances; no custom lightweight replacement storefront.
import fs from 'node:fs';import path from 'node:path';import{createHash,randomBytes,timingSafeEqual}from'node:crypto';import{spawn}from'node:child_process';import{fileURLToPath}from'node:url';import{seal,unseal}from'./vault.mjs';import{createBridge}from'./bot-bridge.mjs';
const admissions=new Map();
const root=process.env.ALIREZA_ROOT||'/var/lib/alirezaserver',pending=new Map(),bridges=new Map();const fail=(m,s=400)=>Object.assign(Error(m),{status:s,code:m});
export const keyFor=id=>createHash('sha256').update('mirza:'+String(id)).digest('hex').slice(0,24);
export function identity(auth){if(!auth||auth.role==='owner'||!['reseller','manager','admin1','admin'].includes(auth.role)||!auth.id||auth.id==='owner'||!auth.caps?.includes('users.create'))throw fail('TENANT_FORBIDDEN',403);return String(auth.id);}
const dir=key=>{if(!/^[a-f0-9]{24}$/.test(key))throw fail('TENANT_INVALID_ID');return path.join(root,'mirza-tenants',key);};
export function read(key){try{return unseal(JSON.parse(fs.readFileSync(dir(key)+'/config.json')),'mirza-tenant');}catch(e){if(e.code==='ENOENT')return null;throw e;}}
function save(key,c){fs.mkdirSync(dir(key),{recursive:true,mode:0o700});const tmp=dir(key)+'/config.new';fs.writeFileSync(tmp,JSON.stringify(seal(c,'mirza-tenant')),{mode:0o600});fs.renameSync(tmp,dir(key)+'/config.json');}
export function assertTokenAvailable(token,except){if(admissions.has(token))throw fail('TENANT_TOKEN_BUSY',409);const base=path.join(root,'mirza-tenants');if(fs.existsSync(base))for(const k of fs.readdirSync(base))if(k!==except&&/^[a-f0-9]{24}$/.test(k)&&read(k)?.token===token)throw fail('TENANT_TOKEN_ALREADY_USED',409);}
export function claimToken(token,except){assertTokenAvailable(token,except);admissions.set(token,except||'owner');return()=>admissions.delete(token);}
