 # the instance identity, so a tenant cannot feed modified PHP to root repair.
 source=source.replace("shutil.chown(APP,user='"+name+"',group='"+name+"')", "shutil.chown(APP,user='root',group='"+name+"')")
 for variable in ['temp','target']:
  source=source.replace("shutil.chown("+variable+",user='"+name+"',group='"+name+"')","shutil.chown("+variable+",user='root',group='"+name+"')")
 begin=source.index("    for path in APP.rglob('*'):")
 end=source.index("    phase('php-runtime',5)",begin)
 block="""    writable=['storage','log','lang/override']
    for path in APP.rglob('*'):
        if path.is_symlink():raise RuntimeError('BOT_SYMLINK_REFUSED')
        rel=path.relative_to(APP).as_posix()
        if any(rel==p or rel.startswith(p+'/') for p in writable):continue
